/**
 * Given an input dataset, replace missing values of a dimension with given
 * imputation strategy. This function does not produce an output matrix, but
 * overwrites the result into the input matrix.
 *
 * @param input Input dataset to apply imputation.
 * @param missingValue User defined missing value; it can be anything.
 * @param dimension Dimension to apply the imputation.
 */
template<typename MatType>
void Impute(MatType& input,
            const typename MatType::elem_type& missingValue,
            const size_t dimension,
            const bool columnMajor = true,
            const std::enable_if_t<IsArma<MatType>::value>* = 0)
{
  if (columnMajor && (dimension >= input.n_rows))
  {
    std::ostringstream oss;
    oss << "Imputer::Impute(): given dimension to impute (" << dimension
        << ") must be less than the number of rows in the matrix ("
        << input.n_rows << ")!" << std::endl;
    throw std::invalid_argument(oss.str());
  }
  else if (!columnMajor && (dimension >= input.n_cols))
  {
    std::ostringstream oss;
    oss << "Imputer::Impute(): given dimension to impute (" << dimension
        << ") must be less than the number of columns in the matrix ("
        << input.n_cols << ")!" << std::endl;
    throw std::invalid_argument(oss.str());
  }

  strategy.Impute(input, missingValue, dimension, columnMajor);

/**
 * Impute function searches through the input looking for mappedValue and
 * replaces it with the user-defined custom value of the given dimension.
 * The result is overwritten to the input, not creating any copy. Custom value
 * must be set when initializing the CustomImputation object.
 *
 * @param input Matrix that contains mappedValue.
 * @param mappedValue Value that the user wants to get rid of.
 * @param dimension Index of the dimension of the mappedValue.
 * @param columnMajor State of whether the input matrix is columnMajor or not.
 */
template<typename MatType>
void Impute(MatType& input,
            const typename MatType::elem_type& missingValue,
            const size_t dimension,
            const bool columnMajor = true)
{
  typedef typename MatType::elem_type T;

  // Here we can use .replace() directly.
  if (columnMajor)
    input.row(dimension).replace(missingValue, (T) customValue);
  else
    input.col(dimension).replace(missingValue, (T) customValue);

template<typename MatType>
void Impute(MatType& input,
            const typename MatType::elem_type& missingValue,
            const size_t dimension,
            const bool columnMajor = true)
{
  static_assert(!IsSparse<MatType>::value, "ListwiseDeletion::Impute(): "
      "sparse matrix imputation is not supported; use a dense matrix "
      "instead!");

  if (std::isnan(missingValue))
  {
    if (columnMajor)
      input.shed_cols(find_nan(input.row(dimension)));
    else
      input.shed_rows(find_nan(input.col(dimension)));
  }
  else
  {
    if (columnMajor)
      input.shed_cols(find(input.row(dimension) == missingValue));
    else
      input.shed_rows(find(input.col(dimension) == missingValue));
  }
}

template<typename T>
static void Impute(arma::Mat<T>& input,
                   const T& missingValue,
                   const size_t dimension,
                   const bool columnMajor = true)
{
  T meanValue = 0;

  #if ARMA_VERSION_MAJOR < 14 || \
      (ARMA_VERSION_MAJOR == 14 && ARMA_VERSION_MINOR < 6)
    // This Armadillo-specific version is used when omit_nan() is not
    // available.
    T sum = 0;
    size_t elems = 0; // Excluding missingValue.

    // Different implementations if we are searching for NaN.
    if (std::isnan(missingValue))
    {
      if (columnMajor)
      {
        #pragma omp parallel for schedule(static)
        for (size_t i = 0; i < input.n_cols; ++i)
        {
          if (!std::isnan(input(dimension, i)))
          {
            ++elems;
            sum += input(dimension, i);
          }
        }
      }
      else
      {
        #pragma omp parallel for schedule(static)
        for (size_t i = 0; i < input.n_rows; ++i)
        {
          if (!std::isnan(input(i, dimension)))
          {
            ++elems;
            sum += input(i, dimension);
          }
        }
      }
    }
    else
    {
      if (columnMajor)
      {
        #pragma omp parallel for schedule(static)
        for (size_t i = 0; i < input.n_cols; ++i)
        {
          if (input(dimension, i) != missingValue)
          {
            ++elems;
            sum += input(dimension, i);
          }
        }
      }
      else
      {
        #pragma omp parallel for schedule(static)
        for (size_t i = 0; i < input.n_rows; ++i)
        {
          if (input(i, dimension) != missingValue)
          {
            ++elems;
            sum += input(i, dimension);
          }
        }
      }
    }

  if (elems == 0)
  {
    throw std::invalid_argument("MeanImputation::Impute(): no non-missing "
        "elements; cannot compute mean!");
  }

  // Now compute the mean.
  meanValue = sum / elems;
#else
  if (std::isnan(missingValue))
  {
    if (columnMajor)
      meanValue = mean(omit_nan(input.row(dimension)));
    else
      meanValue = mean(omit_nan(input.col(dimension)));
  }
  else
  {
    if (columnMajor)
    {
      meanValue = mean(vectorise(input.submat(
          arma::uvec({ static_cast<arma::uword>(dimension) }),
          find(input.row(dimension) != missingValue))));
    }
    else
    {
      meanValue = mean(vectorise(input.submat(
          find(input.col(dimension) != missingValue),
          arma::uvec({ static_cast<arma::uword>(dimension) }))));
    }
  }
#endif

// Replace all values with the computed mean.
if (columnMajor)
  input.row(dimension).replace(missingValue, meanValue);
else
  input.col(dimension).replace(missingValue, meanValue);

template<typename MatType>
static void Impute(MatType& input,
                   const typename MatType::elem_type& missingValue,
                   const size_t dimension,
                   const bool columnMajor = true)
{
  static_assert(!IsSparse<MatType>::value, "MeanImputation::Impute(): "
      "sparse matrix imputation is not supported; use a dense matrix "
      "instead!");

  typedef typename MatType::elem_type ElemType;
  typedef typename GetUColType<MatType>::type UCol;
  ElemType meanValue;
  if (columnMajor)
  {
    UCol indices;
    if (std::isnan(missingValue))
      indices = find_nonnan(input.row(dimension));
    else
      indices = find(input.row(dimension) != missingValue);

    meanValue = mean(vectorise(input.submat(UCol({ dimension }), indices)));
  }
  else
  {
    UCol indices;
    if (std::isnan(missingValue))
      indices = find_nonnan(input.col(dimension));
    else
      indices = find(input.col(dimension) != missingValue);

    meanValue = mean(vectorise(input.submat(indices, UCol({ dimension }))));
  }

  if (columnMajor)
    input.row(dimension).replace(missingValue, meanValue);
  else
    input.col(dimension).replace(missingValue, meanValue);

  #if ARMA_VERSION_MAJOR < 14 || \
      (ARMA_VERSION_MAJOR == 14 && ARMA_VERSION_MINOR < 6)
    // This is used when omit_nan() is not available.

    // If mappedValue is NaN, Armadillo does not quite provide the tools we
    // need so we have to do our own implementation.  Otherwise, we can
    // directly use Armadillo pretty easily.
    arma::Mat<T> tmp;
    if (std::isnan(missingValue))
    {
      if (columnMajor)
        tmp = input.row(dimension);
      else
        tmp = input.col(dimension).t();

      tmp.shed_cols(find_nan(tmp));
    }
    else
    {
      if (columnMajor)
      {
        tmp = input.submat(arma::uvec({ dimension }),
            find(input.row(dimension) != missingValue));
      }
      else
      {
        tmp = input.submat(
            find(input.col(dimension) != missingValue),
            arma::uvec({ dimension }));
      }
    }

    // Compute the median on the extracted elements.
    if (tmp.is_empty())
    {
      throw std::invalid_argument("MedianImputation::Impute(): no non-missing"
          " elements; cannot compute median!");
    }
    medianValue = median(vectorise(tmp));
  #else
    if (std::isnan(missingValue))
    {
      if (columnMajor)
        medianValue = median(omit_nan(input.row(dimension)));
      else
        medianValue = median(omit_nan(input.col(dimension)));
    }
    else
    {
      if (columnMajor)
      {
        medianValue = median(vectorise(input.submat(
            arma::uvec({ static_cast<arma::uword>(dimension) }),
            find(input.row(dimension) != missingValue))));
      }
      else
      {
        medianValue = median(vectorise(input.submat(
            find(input.col(dimension) != missingValue),
            arma::uvec({ static_cast<arma::uword>(dimension) }))));
      }
    }
  #endif

  if (columnMajor)
    input.row(dimension).replace(missingValue, medianValue);
  else
    input.col(dimension).replace(missingValue, medianValue);
}

/**
 * Impute function searches through the input looking for mappedValue and
 * replaces it with the median of the given dimension. The result is
 * overwritten to the input matrix.
 *
 * This overload is used for Bandicoot, where omit_nan() is not available
 * (yet).
 *
 * @param input Matrix that contains mappedValue.
 * @param mappedValue Value that the user wants to get rid of.
 * @param dimension Index of the dimension of the mappedValue.

void BINDING_FUNCTION(util::Params& params, util::Timers& timers)
{
  mat data = std::move(params.Get<mat>("input"));
  const double missingValue = params.Get<double>("missing_value");
  const double customValue = params.Get<double>("custom_value");
  const size_t dimension = (size_t) params.Get<int>("dimension");
  string strategy = params.Get<string>("strategy");

  RequireParamInSet<string>(params, "strategy", { "custom", "mean", "median",
      "listwise_deletion" }, true, "unknown imputation strategy");
  RequireAtLeastOnePassed(params, { "output" }, false,
      "no output will be saved");

  if (!params.Has("dimension"))
  {
    Log::Info << "--dimension is not specified; the imputation will be "
        << "applied to all dimensions."<< endl;
  }

  if (strategy != "custom")
  {
    ReportIgnoredParam(params, "custom_value", "not using custom imputation "
        "strategy");
  }
  else
  {
    RequireAtLeastOnePassed(params, { "custom_value" }, true, "must pass "
        "custom imputation value when using 'custom' imputation strategy");
  }

  const size_t dimStart = params.Has("dimension") ? dimension : 0;
  const size_t dimEnd = params.Has("dimension") ? dimension + 1 : data.n_rows;

for (size_t d = dimStart; d < dimEnd; ++d)
{
  if (strategy == "mean")
  {
    Imputer<MeanImputation> imputer;
    imputer.Impute(data, missingValue, d);
  }
  else if (strategy == "median")
  {
    Imputer<MedianImputation> imputer;
    imputer.Impute(data, missingValue, d);
  }
  else if (strategy == "listwise_deletion")
  {
    Imputer<ListwiseDeletion> imputer;
    imputer.Impute(data, missingValue, d);
  }
  else if (strategy == "custom")
  {
    CustomImputation<> c(customValue);
    Imputer<CustomImputation<>> imputer(c);
    imputer.Impute(data, missingValue, d);
  }
}

params.Get<mat>("output") = std::move(data);

