  bst_bin_t iend = static_cast<bst_bin_t>(cut_ptr[fidx + 1]);
  bst_bin_t n_bins = iend - ibegin;

  GradStats left_sum;
  GradStats right_sum;
  // best split so far
  SplitEntry best;
  best.is_cat = false;  // marker for whether it's updated or not.

  auto f_hist = hist.subspan(cut_ptr[fidx], n_bins);
  auto feature_sum = GradStats{
      std::accumulate(f_hist.data(), f_hist.data() + f_hist.size(), GradientPairPrecise{})};
  GradStats missing;
  auto const &parent = snode_[nidx];
  missing.SetSubstract(parent.stats, feature_sum);

  for (bst_bin_t i = ibegin; i != iend; i += 1) {
    auto split_pt = cut_val[i];

    // missing on left (treat missing as other categories)
    right_sum = GradStats{hist[i]};
    left_sum.SetSubstract(parent.stats, right_sum);
    auto missing_left_chg = static_cast<float>(
        evaluator.CalcSplitGain(*param_, nidx, fidx, GradStats{left_sum}, GradStats{right_sum}) -
        parent.root_gain);
    best.Update(missing_left_chg, fidx, split_pt, true, true, left_sum, right_sum);

    // missing on right (treat missing as chosen category)
    right_sum.Add(missing);
    left_sum.SetSubstract(parent.stats, right_sum);
    auto missing_right_chg = static_cast<float>(
        evaluator.CalcSplitGain(*param_, nidx, fidx, GradStats{left_sum}, GradStats{right_sum}) -
        parent.root_gain);
    best.Update(missing_right_chg, fidx, split_pt, false, true, left_sum, right_sum);
  }

  for (bst_bin_t i = ibegin; i != iend; i += d_step) {
    // start working
    // try to find a split
    left_sum.Add(hist[i].GetGrad(), hist[i].GetHess());
    right_sum.SetSubstract(parent.stats, left_sum);
    bst_float loss_chg;
    bst_float split_pt;
    if (d_step > 0) {
      // forward enumeration: split at right bound of each bin
      loss_chg =
          static_cast<float>(evaluator.CalcSplitGain(*param_, nidx, fidx, GradStats{left_sum},
                                                     GradStats{right_sum}) -
                             parent.root_gain);
      split_pt = cut_val[i];  // not used for partition based
      best.Update(loss_chg, fidx, split_pt, d_step == -1, false, left_sum, right_sum);
    } else {
      // backward enumeration: split at left bound of each bin
      loss_chg =
          static_cast<float>(evaluator.CalcSplitGain(*param_, nidx, fidx, GradStats{right_sum},
                                                     GradStats{left_sum}) -
                             parent.root_gain);
      split_pt = common::HistogramCuts::NumericBinLowerBound(cut_ptr, cut_val, fidx, i);
      best.Update(loss_chg, fidx, split_pt, d_step == -1, false, right_sum, left_sum);
    }
  }

  p_best->Update(best);
  return left_sum;
}

    this->EnumeratePart<+1>(cut, sorted_idx, histogram, fidx, nidx, evaluator, best);
    this->EnumeratePart<-1>(cut, sorted_idx, histogram, fidx, nidx, evaluator, best);
  }
} else {
  auto grad_stats = EnumerateSplit<+1>(cut, histogram, fidx, nidx, evaluator, best);
  if (SplitContainsMissingValues(grad_stats, snode_[nidx])) {
    EnumerateSplit<-1>(cut, histogram, fidx, nidx, evaluator, best);
  }

/** @brief Whether it should traverse to the left branch of a tree. */
template <bool has_categorical, typename TreeView>
XGBOOST_DEVICE bool GetDecision(TreeView const &tree, bst_node_t nid, float fvalue,
                                RegTree::CategoricalSplitMatrix const &cats) {
  if (has_categorical && common::IsCat(cats.split_type, nid)) {
    auto node_categories = cats.categories.subspan(cats.node_ptr[nid].beg, cats.node_ptr[nid].size);
    return common::Decision(node_categories, fvalue);
  } else {
    return fvalue < tree.SplitCond(nid);
  }
}

/**
 * @brief Select the next node using a feature value, with NaN representing missing data.
 *
 * @tparam has_missing Whether feature values may be NaN. When false, callers must
 *                     provide non-NaN values and the missing-value check is omitted.
 * @tparam has_categorical Whether the tree may contain categorical splits.
 * @param fvalue Feature value for the split. With has_missing enabled, NaN selects
 *               the default child before numerical or categorical split evaluation.
 *               Any user-defined missing-value sentinel must already be converted
 *               to NaN by the input loader.
 */
template <bool has_missing, bool has_categorical, typename TreeView>
XGBOOST_DEVICE bst_node_t GetNextNode(TreeView const &tree, const bst_node_t nid, float fvalue,
                                      RegTree::CategoricalSplitMatrix const &cats) {
  if constexpr (has_missing) {
    if (common::CheckNAN(fvalue)) {
      return tree.DefaultChild(nid);
    }
  }
  return tree.LeftChild(nid) + !GetDecision<has_categorical>(tree, nid, fvalue, cats);

template <bool has_missing, bool has_categorical, typename TreeView>
bst_node_t GetLeafIndex(TreeView const &tree, const RegTree::FVec &feat,
                        RegTree::CategoricalSplitMatrix const &cats, bst_node_t nidx) {
  while (!tree.IsLeaf(nidx)) {
    bst_feature_t split_index = tree.SplitIndex(nidx);
    auto fvalue = feat.GetFvalue(split_index);
    nidx = GetNextNode<has_missing, has_categorical>(tree, nidx, fvalue, cats);
  }
  return nidx;
}
